#include <iostream>
#include <string>

int main() {
    std::string name;
    std::string wohnort;
    int alter = 0;

    std::cout << "Vor- und Nachname: ";
    std::getline(std::cin, name);

    std::cout << "Wohnort: ";
    std::getline(std::cin, wohnort);

    std::cout << "Alter: ";
    std::cin >> alter;

    std::cout << std::endl;
    std::cout << "Name: " << name << std::endl;
    std::cout << "Wohnort: " << wohnort << std::endl;
    std::cout << "Alter: " << alter << std::endl;

    return 0;
}

#include <iostream>

int main() {
    int a = 0;
    int b = 0;

    std::cout << "Erste Zahl: ";
    std::cin >> a;
    std::cout << "Zweite Zahl: ";
    std::cin >> b;

    std::cout << a << " + " << b << " = " << a + b << std::endl;
    std::cout << a << " mal " << b << " = " << a * b << std::endl;

    return 0;
}
